export interface PreparationForm {objective: string; editable: string; verification: string; dependencies: string; python: string; node: string; npm: string}
export interface PreparationFile {relative_path: string; role: string; length: number; sha256: string}
export interface PreparationCheck {check_id: string; argv: string[]}
export interface PreparationPlan {request_id: string; repository_id: string; objective: string; files: {relative_path: string; role: string}[]; checks: {check_id: string; profile: string; targets: string[]}[]; limits: {check_seconds: number; total_seconds: number; output_bytes: number}; review_digest?: string}
export interface PreparationReceipt {owner: string; kind: string; request_id: string; repository_id: string; state: string; execution_authorized: boolean; verification_status: string; execution_mode: string; vm_admission_status: string; current_sources_rechecked: boolean; durable: boolean; files: PreparationFile[]; snapshot_sha256: string; review_digest: string; checks: PreparationCheck[]; limits: PreparationPlan['limits']}
export interface PlanBody {summary: string; steps: {path: string; change: string}[]; questions: string[]}
export interface PlanRecord {owner: string; request_id: string; plan_id: string; snapshot_sha256: string; review_digest: string; kind: string; state: string; proposal: PlanBody | null; error_code: string | null; source_status: string; current_sources_rechecked: boolean; execution_authorized: boolean; verification_status: string; model: string; cancel_requested?: boolean}
export interface ProposalFile {path: string; base_sha256: string; proposed_sha256: string; content: string; diff: string}
export interface ProposalBody {summary: string; files: ProposalFile[]; diff: string}
export interface ProposalRecord extends Omit<PlanRecord, 'proposal'> {proposal_id: string; reviewed_plan_sha256: string; apply_authorized: boolean; proposal: ProposalBody | null}
export interface ProposalReview extends PlanRecord {apply_authorized: boolean; source_complete: boolean; source_bytes_limit: number; reviewed_plan_sha256: string; files: {path: string; role: string; sha256: string}[]; checks: PreparationCheck[]}
export interface PreparationHistory {request_id: string; state: string; title: string; execution_authorized: boolean; verification_status: string; retained_inputs_revalidated: boolean}
export interface PlanHistory {plan_id: string; state: string; proposal_revalidated: boolean; execution_authorized: boolean; verification_status: string}
export interface ProposalHistory extends Omit<PlanHistory, 'plan_id'> {proposal_id: string; apply_authorized: boolean}
export interface ProposalCache {review: ProposalReview | null; record: ProposalRecord | null; pending: {id: string; digest: string} | null; cancelRequested: boolean; records: Map<string, ProposalRecord>; items: ProposalHistory[]; nextCursor: string | null; loaded: boolean}
export interface PlanCache {pendingId: string | null; record: PlanRecord | null; cancelRequested: boolean; proposals?: Map<string, ProposalCache>}
export interface PreparationCache {form: PreparationForm; pending: {payload: PreparationPlan; preview: PreparationReceipt} | null; unconfirmedIds: string[]; plans: Map<string, PlanCache>}
export interface PreparationContext {url: string; actor: string; stamp: string; epoch: number; owner: string; cache: PreparationCache; approved: {plan: PreparationPlan; data: PreparationReceipt; formSignature: string} | null; selectedReceipt?: PreparationReceipt | null}
export interface PlanSelection {receipt: PreparationReceipt; key: string; cache: PlanCache}
export interface ProposalSelection extends PlanSelection {parent: PlanRecord & {proposal: PlanBody}; proposalKey: string; proposalCache: ProposalCache}
export interface ProposalState {proposalReview: ProposalReview | null; proposalRecord: ProposalRecord | null; proposalPendingId: string | null; proposalBusy: boolean; proposalCancelBusy: boolean; proposalCancelRequested: boolean; proposalError: string; proposalIdInput: string; proposalSeen: {proposal_id: string; state: string}[]; proposalItems: ProposalHistory[]; proposalNextCursor: string | null; proposalsLoaded: boolean}
export interface PlanningState extends ProposalState {planRecord: PlanRecord | null; planPendingId: string | null; planBusy: boolean; planCancelBusy: boolean; planCancelRequested: boolean; planItems: PlanHistory[]; planNextCursor: string | null; plansLoaded: boolean; planError: string; planIdInput: string}
export interface PreparationState extends PlanningState {phase: string; connected: boolean; busy: boolean; owner: string; form: PreparationForm; preview: PreparationReceipt | null; receipt: PreparationReceipt | null; items: PreparationHistory[]; nextCursor: string | null; historyLoaded: boolean; pendingId: string | null; unconfirmedIds: string[]; error: string}
